// Single source of truth for every species: continuity + Wookieepedia facts,
// all in src/data/species.json. Regenerated by scripts/sync-species.mjs.
import raw from './species.json'

export const allSpecies = raw

export const getSpecies = (id) => allSpecies.find((s) => s.id === id)

// Continuity is an array, e.g. ['canon','legends'] | ['canon'] | ['legends'].
export const getContinuity = (s) =>
  Array.isArray(s.continuity) ? s.continuity : s.continuity ? [s.continuity] : ['legends']

export const inContinuity = (s, mode) => getContinuity(s).includes(mode)
